import React, { useState } from "react";


import { CSSTransition } from "react-transition-group";
import {Link} from "gatsby";

interface IProps {}

function Header(props: IProps) {
  const [showMenu, setShowMenu] = useState(false);

  const toggleHamburger = () => {
    setShowMenu(!showMenu);
  };

  const renderHamburger = () => {
    if (!showMenu) {
      return (
        <div className="hamburgerContainer" onClick={toggleHamburger}>
          <div className="burgerLine"></div>
          <div className="burgerLine"></div>
          <div className="burgerLine"></div>
        </div>
      );
    } else if (showMenu) {
      return (
        <div className="hamburgerContainer" onClick={toggleHamburger}>
          <div className="burgerLineRight">
            <div className="burgerLineLeft"></div>
          </div>
        </div>
      );
    }
  };

  const RenderMobileMenu = () => {
    return (
      <CSSTransition
        in={showMenu}
        timeout={500}
        classNames="mobNav"
        unmountOnExit
        onEnter={() => setShowMenu(true)}
      >
        <div className="mobMenuBg">
          <Link className="navLinkMob" to={"/"}>
            <div className="navTxt">Home</div>
          </Link>
          {/* <Link className="navLinkMob" to={"/about"}>
            <div className="navTxt">About</div>
          </Link> */}
          <Link className="navLinkMob" to={"/creations"}>
              <div className="navTxt">Creations</div>
          </Link>
           {/* <Link className="navLinkMob" to={"/developer"}>
              <div className="navTxt">Developer</div>
          </Link> */}
           <Link className="navLinkMob" to={"/photography"}>
              <div className="navTxt">Photography</div>
            </Link>
        </div>
      </CSSTransition>
    );
  };

  const renderNavMenu = () => {
    return (
      <div className="navContainer">
        <div className="navMenuHolder">
          <Link className="navLink" activeClassName="active" to={"/"}>
            <div className="navMenuTxt">Home</div>
          </Link>
          {/* <Link className="navLink" activeClassName="active" to={"/about"}>
            <div className="navMenuTxt">About</div>
          </Link> */}
           <Link className="navLink" activeClassName="active" to={"/creations"}>
              <div className="navMenuTxt">Creations</div>
          </Link>
          {/* <Link className="navLink" activeClassName="active" to={"/developer"}>
              <div className="navMenuTxt">Developer</div>
          </Link> */}
           <Link className="navLink" activeClassName="active" to={"/photography"}>
              <div className="navMenuTxt">Photography</div>
            </Link>
        </div>
        {renderHamburger()}
      </div>
    );
  };

  return (
    <div>
      <div className="main-header">
        <div className="main-header__navLogo">
          <Link className="navLink" to={"/"}>

          </Link>
          <span className="nav-tagline">Design. Code. Capture. Create.</span>
          {renderNavMenu()}
        </div>
        {RenderMobileMenu()}
      </div>
    </div>
  );
}

export default Header;
